// ---------- GBK 编码器：遍历全部双字节码位，用 WHATWG gbk 解码器反推 ----------
function buildGbkEncoder() {
  const decoder = new TextDecoder("gbk", { fatal: true });
  const map = new Map();
  for (let lead = 0x81; lead <= 0xfe; lead += 1) {
    for (let trail = 0x40; trail <= 0xfe; trail += 1) {
      if (trail === 0x7f) continue;
      let ch;
      try { ch = decoder.decode(new Uint8Array([lead, trail])); } catch { continue; }
      if ([...ch].length === 1 && ch !== "\uFFFD" && !map.has(ch)) map.set(ch, [lead, trail]);
    }
  }
  return (text) => {
    const bytes = [];
    for (const ch of text) {
      const code = ch.codePointAt(0);
      if (code < 0x80) { bytes.push(code); continue; }
      const pair = map.get(ch);
      if (!pair) throw new Error(`GBK 无法编码字符 ${ch} U+${code.toString(16)}`);
      bytes.push(...pair);
    }
    return Buffer.from(bytes);
  };
}

function csvCell(value) {
  const text = String(value ?? "");
  return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}
const csvLine = (cells) => cells.map(csvCell).join(",");

