// ---------- 3. 花名册.xlsx：表头在第 1 行 ----------
// 真日期单元格写成整数序列号 + 日期格式（Excel 真实存储方式）。不要把 Date 交给
// aoa_to_sheet：SheetJS 按生成机器的本地时区换算，会写出带小数的序列号，读回时差一天。
const EXCEL_EPOCH = Date.UTC(1899, 11, 30);
const d = (y, m, day) => ({ serial: (Date.UTC(y, m - 1, day) - EXCEL_EPOCH) / 86400000 });
const toSheetAoa = (aoa) => aoa.map((row) => row.map((v) => (v && typeof v === "object" && "serial" in v ? v.serial : v)));
function markDateCells(ws, aoa, format) {
  aoa.forEach((row, r) => row.forEach((v, c) => {
    if (v && typeof v === "object" && "serial" in v) {
      const cell = ws[XLSX.utils.encode_cell({ r, c })];
      cell.t = "n";
      cell.z = format;
    }
  }));
}
